// Thread safe. This function can be disabled with `outputStateIdToStringFunction` setting.
char const * ContextSm_state_id_to_string(ContextSm_StateId id)
{
    switch (id)
    {
        case ContextSm_StateId_ROOT: return "ROOT";
        case ContextSm_StateId_RUNNING: return "RUNNING";
        case ContextSm_StateId_FIELD: return "FIELD";
        case ContextSm_StateId_FIELDPAGE: return "FIELDPAGE";
        case ContextSm_StateId_CLASSIC: return "CLASSIC";
        case ContextSm_StateId_MANUAL: return "MANUAL";
        case ContextSm_StateId_MANUALDIRECT: return "MANUALDIRECT";
        case ContextSm_StateId_MANUALQUICKJUMP: return "MANUALQUICKJUMP";
        case ContextSm_StateId_MENU: return "MENU";
        case ContextSm_StateId_BANDMENU: return "BANDMENU";
        case ContextSm_StateId_ENGINEMENU: return "ENGINEMENU";
        case ContextSm_StateId_INSTRUMENT: return "INSTRUMENT";
        case ContextSm_StateId_UTILITY: return "UTILITY";
        default: return "?";
    }
}

