// Returns the parent state for a given state. Returns ROOT if input has no parent.
// Thread safe. This function can be disabled with `outputGetParentIdFunction` setting.
ContextSm_StateId ContextSm_get_parent_id(ContextSm_StateId id)
{
    switch (id)
    {
        case ContextSm_StateId_ROOT: return ContextSm_StateId_ROOT;
        case ContextSm_StateId_RUNNING: return ContextSm_StateId_ROOT;
        case ContextSm_StateId_FIELD: return ContextSm_StateId_RUNNING;
        case ContextSm_StateId_FIELDPAGE: return ContextSm_StateId_FIELD;
        case ContextSm_StateId_CLASSIC: return ContextSm_StateId_FIELDPAGE;
        case ContextSm_StateId_MANUAL: return ContextSm_StateId_FIELDPAGE;
        case ContextSm_StateId_MANUALDIRECT: return ContextSm_StateId_MANUAL;
        case ContextSm_StateId_MANUALQUICKJUMP: return ContextSm_StateId_MANUAL;
        case ContextSm_StateId_MENU: return ContextSm_StateId_FIELD;
        case ContextSm_StateId_BANDMENU: return ContextSm_StateId_MENU;
        case ContextSm_StateId_ENGINEMENU: return ContextSm_StateId_MENU;
        case ContextSm_StateId_INSTRUMENT: return ContextSm_StateId_RUNNING;
        case ContextSm_StateId_UTILITY: return ContextSm_StateId_RUNNING;
        default: return ContextSm_StateId_ROOT;
    }
}
